public sealed class RecordingSettlementGateway : ISettlementGateway
{
    private readonly GatewayResult _result;

    public RecordingSettlementGateway(GatewayResult result)
    {
        _result = result;
    }

    public List<SettlementGatewayCall> Calls { get; } = new List<SettlementGatewayCall>();

    public GatewayResult Submit(string merchantId, string currency, decimal amount, IReadOnlyList<string> references)
    {
        Calls.Add(new SettlementGatewayCall(merchantId, currency, amount, references.ToArray()));
        return _result;
    }
}

public sealed record SettlementGatewayCall(string MerchantId, string Currency, decimal Amount, IReadOnlyList<string> References);

